-- Module thử ghi-chu (PHASE-014 W1): bảng ghi chú theo đơn vị.
CREATE TABLE notes (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id  bigint NOT NULL,
  body       text   NOT NULL,
  created_by text   NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE notes FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON notes USING (public.bizcity_tenant_visible(tenant_id)) WITH CHECK (public.bizcity_tenant_visible(tenant_id));
COMMENT ON TABLE notes IS 'Ghi chú của đơn vị (module thử ghi-chu).';
COMMENT ON COLUMN notes.body IS 'Nội dung ghi chú.';
